#!/usr/bin/env python3
"""Convert a local SMG dump in place for the 3DS port.

Run without arguments to open the Tkinter GUI, or use the CLI options for automation:
    python3 convert_smg_files.py --source smg/files --native smg/native

In local mode, the script also creates the native Citro3D model files required by the 3DS
renderer. They are written next to the selected files folder, at sdmc:/smg/native. Original
Wii J3D data and archives already converted by this tool are both accepted: converted J3D
tables are detected and restored before native extraction. Use --discover-native to inventory
native models missing from an already converted files folder (without needing the Dolphin dump).
Use --native-only to generate missing native models without changing the files folder.
An .n3d left by an older version of the port (another format version) counts as missing and is
written again; the game rejects it.

The GUI asks at its first start for the unconverted files Dolphin extracted, and keeps the path in
~/.smg3ds_converter.json: outdated converted files are converted anew from them.

The converter is embedded; no project checkout or third-party Python package is required.
The input tree is overwritten in place. Make a backup before running. The original files in
sdmc:/smg/files must be kept: native models only replace the geometry draw path, while the
game still needs the archives for textures, animations, layouts, metadata, audio, and fallback
paths.
"""

