PACK_MAGIC = b"SPK2"
PACK_FILE_LIMIT = 2 * 1024 * 1024
PACK_UNPACKED = 0xFFFFFFFF
MOVIE_VERSION = 0x3D50001  # movie.VERSION: a THP already converted for the 3DS
NO_WINDOW = getattr(subprocess, "CREATE_NO_WINDOW", 0)  # Windows: no console window for child processes


# Progress protocol: the GUI reads "@@PROGRESS step steps percent name|detail" lines (percent -1
# while the total is unknown); every other line goes to its log.
_steps = []
_last_progress = [0.0]


def _set_steps(*names):
    _steps[:] = names


def _progress(name, done, total, detail="", force=False):
    now = time.monotonic()
    if not force and total and done < total and now - _last_progress[0] < 0.1:
        return
    _last_progress[0] = now
    step = _steps.index(name) + 1 if name in _steps else 0
    percent = -1.0 if not total else 100.0 * min(done, total) / total
    print(f"@@PROGRESS {step} {len(_steps)} {percent:.1f} {name}|{detail}", flush=True)


def _log(text):
    print(text, flush=True)


def _is_hidden(path):
    # Dot files: macOS writes ._name and .DS_Store on FAT cards; this tool's own temporaries.
    return path.name.startswith(".")


LOG_FOLDER = "conv_logs"  # next to the script, which can sit in the tree it converts


def _list_files(root, report=None):
    """Every file under root (sorted, hidden ones left out); report(count) while walking."""
    found = []
    for directory, dirs, names in os.walk(root):
        dirs[:] = sorted(d for d in dirs if not d.startswith(".") and d != LOG_FOLDER)
        for name in names:
            if not name.startswith("."):
                found.append(Path(directory) / name)
                if report and len(found) % 250 == 0:
                    report(len(found))
    return sorted(found)


def _tools_dir():
    """Per-user folder for the ffmpeg this tool downloads."""
    if os.name == "nt":
        base = os.environ.get("LOCALAPPDATA") or Path.home() / "AppData" / "Local"
    elif sys.platform == "darwin":
        base = Path.home() / "Library" / "Caches"
    else:
        base = os.environ.get("XDG_CACHE_HOME") or Path.home() / ".cache"
    return Path(base) / "smg3ds-converter"


# Static ffmpeg builds with libx264, per (system, machine).
_GITHUB_FFMPEG = "https://github.com/BtbN/FFmpeg-Builds/releases/download/latest/ffmpeg-master-latest-"
_MAC_FFMPEG = "https://ffmpeg.martin-riedl.de/redirect/latest/macos/%s/release/ffmpeg.zip"
FFMPEG_DOWNLOADS = {
    ("windows", "x86_64"): _GITHUB_FFMPEG + "win64-gpl.zip",
    ("windows", "arm64"): _GITHUB_FFMPEG + "winarm64-gpl.zip",
    ("linux", "x86_64"): _GITHUB_FFMPEG + "linux64-gpl.tar.xz",
    ("linux", "arm64"): _GITHUB_FFMPEG + "linuxarm64-gpl.tar.xz",
    ("darwin", "x86_64"): _MAC_FFMPEG % "amd64",
    ("darwin", "arm64"): _MAC_FFMPEG % "arm64",
}


def _ffmpeg_works(path):
    """True when path runs and has the H.264 encoder the movies need."""
    try:
        result = subprocess.run([str(path), "-hide_banner", "-encoders"], capture_output=True, text=True,
                                timeout=60, stdin=subprocess.DEVNULL, creationflags=NO_WINDOW)
    except (OSError, subprocess.SubprocessError):
        return False
    return result.returncode == 0 and "libx264" in result.stdout


def _download(url, target, step):
    """url to target, with progress; curl when Python's own HTTPS fails (e.g. macOS Python
    without its certificates installed)."""
    try:
        request = urllib.request.Request(url, headers={"User-Agent": "smg3ds-converter"})
        with urllib.request.urlopen(request, timeout=60) as response, target.open("wb") as out:
            total = int(response.headers.get("Content-Length") or 0)
            done = 0
            while True:
                chunk = response.read(1 << 20)
                if not chunk:
                    break
                out.write(chunk)
                done += len(chunk)
                _progress(step, done, total, f"Downloading ffmpeg: {done >> 20} of {total >> 20} MB")
        return
    except OSError as error:
        if shutil.which("curl") is None:
            raise
        _log(f"Download through Python failed ({error}); using curl.")
    head = subprocess.run(["curl", "-sIL", url], capture_output=True, text=True, creationflags=NO_WINDOW).stdout
    lengths = [line.split(":", 1)[1].strip() for line in head.splitlines() if line.lower().startswith("content-length:")]
    total = int(lengths[-1]) if lengths and lengths[-1].isdigit() else 0
    process = subprocess.Popen(["curl", "-sL", "--fail", "-o", str(target), url], creationflags=NO_WINDOW)
    while process.poll() is None:
        done = target.stat().st_size if target.exists() else 0
        _progress(step, done, total, f"Downloading ffmpeg: {done >> 20} of {total >> 20} MB")
        time.sleep(0.25)
    if process.returncode:
        raise OSError(f"curl failed ({process.returncode}) for {url}")


class _CountingReader:
    """A file read through tarfile's stream mode, counting the compressed bytes read."""

    def __init__(self, stream, step, total):
        self.stream, self.step, self.total, self.done = stream, step, total, 0

    def read(self, size=-1):
        data = self.stream.read(size)
        self.done += len(data)
        _progress(self.step, self.done, self.total, "Extracting ffmpeg...")
        return data


def _extract_ffmpeg(archive, target, step):
    name = "ffmpeg.exe" if os.name == "nt" else "ffmpeg"
    temporary = target.with_name(target.name + ".tmp")
    found = False
    if archive.suffix == ".zip":
        with zipfile.ZipFile(archive) as bundle:
            member = next((i for i in bundle.infolist() if Path(i.filename).name == name), None)
            if member is not None:
                found = True
                with bundle.open(member) as source, temporary.open("wb") as out:
                    done = 0
                    while chunk := source.read(1 << 20):
                        out.write(chunk)
                        done += len(chunk)
                        _progress(step, done, member.file_size, "Extracting ffmpeg...")
    else:
        with archive.open("rb") as raw:
            with tarfile.open(fileobj=_CountingReader(raw, step, archive.stat().st_size), mode="r|xz") as bundle:
                for member in bundle:
                    if member.isfile() and Path(member.name).name == name:
                        with bundle.extractfile(member) as source, temporary.open("wb") as out:
                            shutil.copyfileobj(source, out, 1 << 20)
                        found = True
                        break
    if not found:
        raise OSError(f"{name} not found in {archive.name}")
    temporary.chmod(0o755)
    os.replace(temporary, target)


def _ensure_ffmpeg(movie, step):
    """An ffmpeg with libx264: the one downloaded before, the system's, or downloaded now (and,
    on macOS, Homebrew's as a last resort). None when none can be had."""
    tools = _tools_dir()
    own = tools / ("ffmpeg.exe" if os.name == "nt" else "ffmpeg")
    _progress(step, 0, None, "Looking for ffmpeg...", force=True)
    if own.is_file() and _ffmpeg_works(own):
        return str(own)
    system = movie.find_ffmpeg()
    if system and _ffmpeg_works(system):
        return system
    if system:
        _log(f"ffmpeg at {system} has no H.264 encoder (libx264); downloading one that has it.")
    machine = platform.machine().lower()
    machine = {"amd64": "x86_64", "x64": "x86_64", "aarch64": "arm64", "arm64e": "arm64"}.get(machine, machine)
    key = ("windows" if os.name == "nt" else sys.platform if sys.platform == "darwin" else "linux", machine)
    url = FFMPEG_DOWNLOADS.get(key)
    if url:
        _log(f"ffmpeg not found: downloading it for {key[0]} {key[1]} into {tools}")
        tools.mkdir(parents=True, exist_ok=True)
        archive = tools / (".download.tar.xz" if url.endswith(".tar.xz") else ".download.zip")
        try:
            _download(url, archive, step)
            _extract_ffmpeg(archive, own, step)
        except (OSError, zipfile.BadZipFile, tarfile.TarError) as error:
            _log(f"ffmpeg download failed: {error}")
        finally:
            if archive.exists():
                archive.unlink()
        if own.is_file() and _ffmpeg_works(own):
            _log(f"ffmpeg ready: {own}")
            return str(own)
    else:
        _log(f"No ffmpeg download for {key[0]} {key[1]}.")
    if sys.platform == "darwin" and shutil.which("brew"):
        _log("Installing ffmpeg with Homebrew (brew install ffmpeg)...")
        process = subprocess.Popen(["brew", "install", "ffmpeg"], stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                   text=True, errors="replace")
        for line in process.stdout:
            _log(line.rstrip())
            _progress(step, 0, None, "Homebrew is installing ffmpeg...")
        process.wait()
        system = movie.find_ffmpeg()
        if system and _ffmpeg_works(system):
            return system
    return None


def build_file_pack(files_root, native_root):
    """Write smg/cache (pack.bin and index.bin) next to the files folder.

    Opening a file on the console's SD card walks its folder (about 157 ms in ObjectData), so the
    game reads files up to PACK_FILE_LIMIT from one pack instead. The index lists every file of
    both trees, larger ones as left on the card: a path it does not list is missing, and the game
    does not look for it on the card (platform/3ds/host/fs.c). Run again after changing the files.
    """
    step = "SD cache"
    cache = files_root.parent / "cache"
    cache.mkdir(parents=True, exist_ok=True)
    trees = [(files_root, "sdmc:/smg/files/")]
    if native_root.is_dir():
        trees.append((native_root, "sdmc:/smg/native/"))
    entries = []
    for tree, prefix in trees:
        listed = _list_files(tree, lambda count: _progress(step, 0, None, f"Listing files: {count}"))
        for path in listed:
            if path.suffix != ".py":
                entries.append((path, prefix + path.relative_to(tree).as_posix()))
    pack_path, index_path = cache / "pack.bin", cache / "index.bin"
    pack_temporary = cache / f".pack.{os.getpid()}.tmp"
    index_temporary = cache / f".index.{os.getpid()}.tmp"
    packed = packed_bytes = 0
    try:
        with pack_temporary.open("wb") as pack, index_temporary.open("wb") as index:
            index.write(PACK_MAGIC)
            for number, (path, name) in enumerate(entries, 1):
                _progress(step, number - 1, len(entries), name)
                size = path.stat().st_size
                offset = PACK_UNPACKED
                if size <= PACK_FILE_LIMIT:
                    offset = pack.tell()
                    pack.write(path.read_bytes())
                    packed += 1
                    packed_bytes += size
                    _log(f"cache: {name}")
                else:
                    _log(f"cache: {name} (listed, read from the card: {size >> 20} MB)")
                encoded = name.encode("utf-8")
                if len(encoded) >= 256:
                    raise SystemExit(f"Path too long for the file cache: {name}")
                index.write(struct.pack("<III", offset, size, len(encoded)) + encoded)
        _progress(step, len(entries), len(entries), "Writing pack.bin and index.bin...", force=True)
        os.replace(pack_temporary, pack_path)
        os.replace(index_temporary, index_path)
    finally:
        for temporary in (pack_temporary, index_temporary):
            if temporary.exists():
                temporary.unlink()
    print(f"File cache: {len(entries)} files listed, {packed} packed ({packed_bytes // (1024 * 1024)} MB) in {cache}")
    print("Copy the cache folder to sdmc:/smg/cache together with files and native.")
    return 0


# Converted files stay as they were when the converter changes, and an in-place conversion leaves no
# original to convert them from again. Each entry: the version of the tree that needs these files
# (paths under smg/files) converted anew, from the original extraction (--originals).
FILE_UPDATES = (
    (2, ("ObjectData/*Sky.arc",)),  # sky CMPR textures not re-encoded (texreduce.SKY_CMPR_LIMIT)
    (3, ("ObjectData/*.arc",)),  # models with their textures' halvings, for the indirect displacement
    (4, ("ObjectData/*.arc",)),  # models with their textures' value ranges, for the indirect displacement
    (5, ("ObjectData/*.arc",)),  # indirect textures stretched to the whole range of values
    (6, ("ObjectData/*.arc",)),  # again: version 5 was first written by a converter with its old embedded modules
    (7, ("ObjectData/*.arc",)),  # model textures in the 3DS's compressed formats (texreduce._compressed)
    # Version 9 re-encoded the music streams in AFC ADPCM; with them the music stopped for good at
    # random moments (CIA 0.21.1). Version 10 makes the streams PCM16 again, as on the disc.
    (10, ("AudioRes/Stream/*.ast",)),  # music streams back to PCM16 (audio.convert_stream)
)
FILES_VERSION = 10

# Native models written again although their format version is current, as FILE_UPDATES does for
# converted files: a converter change that alters some .n3d without a new format.
NATIVE_UPDATES = (
    (8, ("ObjectData/*Middle.arc", "ObjectData/*Low.arc")),  # LOD models with their main model's colour animations
)


############################################################################
# Game data kept inside main.dol
#
# The Wii executable carries three data files in its .rodata (the story's
# steps, the galaxies' list, the disc and save error texts). The 3DS port
# contains no Nintendo data, so it reads them from sdmc:/smg/port/ at startup
# (platform/3ds/rvl/port_data.cpp). Here they are cut out of the user's own
# main.dol (sys/main.dol, next to the files/ folder Dolphin extracts), converted
# like every other game file, and written there.
############################################################################

# The USA main.dol, as the decomp's Wii build checks it (config/RMGE01/build.sha1).
MAIN_DOL_SHA1 = "9a71008ae1ee9010e267fa67d1f0b0d4f0e895dd"
# File name on the SD card, then its address and size in RMGE01's main.dol
# (config/RMGE01/symbols.txt: cStoryProgressTable, cGalaxyInfoTable, cErrorMessageArchive).
PORT_DATA = (
    ("StoryProgressTable.bcsv", 0x8053C620, 0x1E0),
    ("GalaxyInfoTable.bcsv", 0x8053C800, 0xD20),
    ("ErrorMessageArchive.arc", 0x8053DFE0, 0x9AC0),
)


def _port_data_folder(root):
    """sdmc:/smg/port beside sdmc:/smg/files."""
    return root.parent / "port"


def _main_dol_for(*folders):
    """sys/main.dol beside one of these files/ folders, or None."""
    for folder in folders:
        if folder is not None:
            candidate = folder.parent / "sys" / "main.dol"
            if candidate.is_file():
                return candidate
    return None


def _dol_bytes(dol, address, size):
    """size bytes at a memory address of a DOL: its header lists 7 code and 11 data sections,
    each with a file offset (0x00), a load address (0x48) and a size (0x90)."""
    for index in range(18):
        offset = int.from_bytes(dol[index * 4 : index * 4 + 4], "big")
        start = int.from_bytes(dol[0x48 + index * 4 : 0x4C + index * 4], "big")
        length = int.from_bytes(dol[0x90 + index * 4 : 0x94 + index * 4], "big")
        if start <= address and address + size <= start + length:
            return dol[offset + address - start : offset + address - start + size]
    raise ValueError(f"address 0x{address:08X} is in no section of main.dol")


def _port_data_missing(root):
    folder = _port_data_folder(root)
    return [name for name, _, _ in PORT_DATA if not (folder / name).is_file()]


def _files_version_path(root):
    return root.parent / "files_version.txt"


def _files_version(root):
    try:
        return int(_files_version_path(root).read_text(encoding="ascii"))
    except (OSError, ValueError):
        return 0


def _outdated_native(root):
    """Relative source archives (under smg/files) whose native models NATIVE_UPDATES renews."""
    version = _files_version(root)
    outdated = set()
    for needed, patterns in NATIVE_UPDATES:
        if needed <= version:
            continue
        for pattern in patterns:
            outdated.update(path.relative_to(root) for path in root.glob(pattern))
    return outdated


def _outdated_files(root):
    """Converted files of the tree at root an older converter wrote and a newer one changes."""
    version = _files_version(root)
    outdated = {}  # each file once, however many updates list it
    for needed, patterns in FILE_UPDATES:
        if needed <= version:
            continue
        for pattern in patterns:
            for path in sorted(root.glob(pattern)):
                if path in outdated:
                    continue
                with path.open("rb") as stream:
                    head = stream.read(16)
                # Converted archives, and converted streams in AFC ADPCM (format byte 0, written by
                # version 9; the disc's streams are PCM16, format byte 1).
                if head[:4] == b"CRAR" or (head[:4] == b"MRTS" and head[9:10] == b"\x00"):
                    outdated[path] = None
    return list(outdated)


class _LogTee:
    """A stream that also writes its lines to the log file, without the GUI's progress lines."""

    def __init__(self, stream, log):
        self.stream, self.log, self.pending = stream, log, ""

    def write(self, text):
        written = self.stream.write(text)
        self.pending += text
        lines = self.pending.split("\n")
        self.pending = lines.pop()
        for line in lines:
            if not line.startswith("@@PROGRESS "):
                self.log.write(line + "\n")
        self.log.flush()
        return written

    def __getattr__(self, name):
        return getattr(self.stream, name)


def _start_log():
    """Each operation's output also goes to conv_logs/, next to this script."""
    try:
        folder = Path(__file__).resolve().parent / LOG_FOLDER
        folder.mkdir(exist_ok=True)
        log = (folder / time.strftime("conv_%Y-%m-%d_%H-%M-%S.txt")).open("a", encoding="utf-8")
    except OSError as error:
        print(f"Warning: the log file cannot be written: {error}")
        return
    log.write(f"{time.strftime('%Y-%m-%d %H:%M:%S')} {' '.join(sys.argv[1:])}\n")
    sys.stdout = _LogTee(sys.stdout, log)
    sys.stderr = _LogTee(sys.stderr, log)


def main():
    parser = argparse.ArgumentParser(description="Convert local SMG files and generate native 3DS models.")
    parser.add_argument("--source", help="local extracted smg/files folder for in-place conversion")
    parser.add_argument(
        "--discover-native",
        action="store_true",
        help="list native models missing from an already converted local files folder",
    )
    parser.add_argument(
        "--native-only",
        action="store_true",
        help="generate missing native models without converting the local files folder",
    )
    parser.add_argument("--native", help="native model folder (default: sibling of --source)")
    parser.add_argument(
        "--originals",
        help="original extracted game files, unconverted: outdated files of --source are converted anew from them",
    )
    parser.add_argument(
        "--only",
        choices=("copy", "update", "native", "convert", "movies"),
        help="one part alone: copy the missing files from --originals, update the outdated files, "
             "native models, game file conversion, or movies",
    )
    parser.add_argument(
        "--pack-only",
        action="store_true",
        help="only write the console's file cache (smg/cache) for an already converted folder",
    )
    parser.add_argument("--gui", action="store_true", help="open the graphical interface")
    parser.add_argument("--validated", action="store_true", help=argparse.SUPPRESS)  # the GUI validated already
    args = parser.parse_args()

    if args.gui or len(sys.argv) == 1:
        run_gui()
        return

    _start_log()
    root = Path(args.source).expanduser().resolve() if args.source else Path(__file__).resolve().parent
    if args.discover_native and args.native_only:
        raise SystemExit("--discover-native and --native-only cannot be used together")
    if args.pack_only:
        _set_steps("SD cache")
    elif args.discover_native:
        _set_steps("Missing native models")
    elif args.native_only:
        _set_steps("Updating files", "Native models", "SD cache")
    elif args.only:
        _set_steps(*{"copy": ("Copying original files",), "update": ("Updating files",), "native": ("Native models",),
                     "convert": ("Checking files", "Converting files"), "movies": ("Movies",)}[args.only])
    elif args.originals:
        _set_steps("Copying original files", "Updating files", "Native models", "Checking files", "Converting files",
                   "Movies", "SD cache")
    else:
        _set_steps("Updating files", "Native models", "Checking files", "Converting files", "Movies", "SD cache")
    # With the originals, the whole operation starts by filling the folder.
    fills_folder = args.only == "copy" or (args.originals and not args.only and not args.native_only and not args.pack_only
                                           and not args.discover_native)
    if not args.validated and not fills_folder:
        validation_errors, validation_warnings = _validate_source_tree(root)
        if validation_errors:
            raise SystemExit(
                "The selected directory is not a valid extracted SMG files tree:\n"
                + "\n".join(f"- {error}" for error in validation_errors)
            )
        for warning in validation_warnings:
            print(f"Warning: {warning}")
    if args.pack_only:
        native_root = Path(args.native).expanduser().resolve() if args.native else root.parent / "native"
        return build_file_pack(root, native_root)

    bundle = base64.b64decode("".join(_BUILDER_ZIP_B64))
    with tempfile.TemporaryDirectory(prefix="smg3ds-converter-") as module_dir:
        with zipfile.ZipFile(io.BytesIO(bundle)) as archive:
            archive.extractall(module_dir)
        sys.path.insert(0, module_dir)
        from build_files import Converter, SKIPPED_DIRS
        import movie
        import j3d
        import yaz0
        with zipfile.ZipFile(io.BytesIO(base64.b64decode("".join(_NATIVE_ZIP_B64)))) as native_archive:
            native_archive.extractall(module_dir)
        import n3d
        import far

        def already_converted(path, data):
            if data[:4] in (b"CRAR", b"<_AA"):
                return True
            signatures = {".brlyt": b"TYLR", ".brlan": b"NALR", ".brfnt": b"TNFR", ".ast": b"MRTS"}
            if data[:4] == signatures.get(path.suffix.lower()):
                return True
            if path.suffix.lower() == ".tpl" and data[:4] == b"\x30\xaf\x20\x00":
                return True
            if path.suffix.lower() == ".bmg" and len(data) >= 0x20:
                be_count = int.from_bytes(data[0x0C:0x10], "big")
                le_count = int.from_bytes(data[0x0C:0x10], "little")
                if le_count <= 32 < be_count:
                    return True
            return False

        # A RARC as the Wii stores it, or already converted to little-endian by this tool.
        rarc_magics = (b"RARC", b"CRAR")

        def native_rarc_files(data):
            if data[:4] not in rarc_magics:
                return
            # Original RARCs are big-endian; build_files.py writes the magic as "CRAR" and the
            # tables little-endian. Reading both makes native generation and discovery work
            # on an already converted files folder.
            byteorder = "big" if int.from_bytes(data[8:12], "big") in (0x20, 0x24) else "little"
            info = int.from_bytes(data[8:12], byteorder)
            data_start = info + int.from_bytes(data[12:16], byteorder)
            file_count = int.from_bytes(data[info + 8 : info + 12], byteorder)
            file_offset = info + int.from_bytes(data[info + 12 : info + 16], byteorder)
            string_offset = info + int.from_bytes(data[info + 20 : info + 24], byteorder)
            for index in range(file_count):
                entry = file_offset + index * 0x14
                flags_name = int.from_bytes(data[entry + 4 : entry + 8], byteorder)
                offset = int.from_bytes(data[entry + 8 : entry + 12], byteorder)
                size = int.from_bytes(data[entry + 12 : entry + 16], byteorder)
                if not (flags_name >> 24) & 1:
                    continue
                name_start = string_offset + (flags_name & 0xFFFFFF)
                name_end = data.index(b"\0", name_start)
                name = data[name_start:name_end].decode("cp932")
                content = data[data_start + offset : data_start + offset + size]
                if yaz0.is_compressed(content):
                    content = yaz0.decompress(content)
                yield name, content

        def discover_native_files(root, native_root, source_files):
            """Report model paths that have no corresponding .n3d file."""
            missing = []
            models = 0
            archives = [path for path in source_files if path.suffix.lower() in (".arc", ".bdl", ".bmd")]
            for number, path in enumerate(archives, 1):
                _progress("Missing native models", number - 1, len(archives), str(path.relative_to(root)))
                data = path.read_bytes()
                if yaz0.is_compressed(data):
                    data = yaz0.decompress(data)
                members = list(native_rarc_files(data)) if data[:4] in rarc_magics else [(path.name, data)]
                relative_archive = path.relative_to(root)
                for member, content in members:
                    if not n3d.is_j3d_model(content):
                        continue
                    models += 1
                    target = native_root / relative_archive / (Path(member).stem + ".n3d")
                    if not is_current_native(target):
                        missing.append(target.relative_to(native_root))
            _progress("Missing native models", len(archives), len(archives), "", force=True)
            report = native_root / "missing-native.txt"
            native_root.mkdir(parents=True, exist_ok=True)
            report.write_text(
                "Missing native models: %d of %d discovered\n%s\n"
                % (len(missing), models, "\n".join(str(path) for path in missing)),
                encoding="utf-8",
            )
            print(f"Native models: {len(missing)} missing of {models} discovered")
            print(f"Missing-model report: {report}")
            for path in missing:
                print(path)
            return 0

        def is_converted_j3d(data):
            return (
                data[:4] == b"2D3J"
                and data[4:8] in (b"4ldb", b"3dmb", b"2dmb")
                and len(data) >= 0x20
                and int.from_bytes(data[8:12], "little") == len(data)
            )

        def is_current_native(target):
            """True for an .n3d written by this converter's format version (the game rejects others)."""
            try:
                with target.open("rb") as stream:
                    header = stream.read(8)
            except OSError:
                return False
            return header[:4] == b"N3D1" and int.from_bytes(header[4:8], "little") == n3d.VERSION

        def is_current_far(target):
            """True for a .far (far model, or the mark of none) written by this converter's version."""
            try:
                with target.open("rb") as stream:
                    return far.is_current(stream.read(8))
            except OSError:
                return False

        def write_atomically(target, data):
            target.parent.mkdir(parents=True, exist_ok=True)
            temporary = target.with_name(f".{target.name}.{os.getpid()}.tmp")
            try:
                temporary.write_bytes(data)
                os.replace(temporary, target)
            finally:
                if temporary.exists():
                    temporary.unlink()

        def generate_native_files(root, native_root, source_files, renew=frozenset()):
            """renew: relative archives whose models are written again even when current. Also
            each model's far model (far.py), when its .far is missing or older."""
            stats = n3d.Stats()
            far_written = 0
            generated = 0
            skipped = 0
            replaced = 0  # existing models written again (older format, or NATIVE_UPDATES)
            failures = []
            native_root.mkdir(parents=True, exist_ok=True)

            archives = [path for path in source_files if path.suffix.lower() in (".arc", ".bdl", ".bmd")]
            for index, path in enumerate(archives, 1):
                _progress("Native models", index - 1, len(archives),
                          f"{path.relative_to(root)} ({generated} written, {skipped} already present)")
                data = path.read_bytes()
                if yaz0.is_compressed(data):
                    data = yaz0.decompress(data)
                members = list(native_rarc_files(data)) if data[:4] in rarc_magics else [(path.name, data)]
                relative_archive = path.relative_to(root)
                animations = members
                parent_name = n3d.lod_parent_archive(path.name)
                parent = path.with_name(parent_name) if parent_name is not None else None
                if parent is not None and parent.is_file() and any(n3d.is_j3d_model(c) for _, c in members):
                    parent_data = parent.read_bytes()
                    if yaz0.is_compressed(parent_data):
                        parent_data = yaz0.decompress(parent_data)
                    if parent_data[:4] in rarc_magics:
                        animations = members + list(native_rarc_files(parent_data))
                for member, content in members:
                    if not n3d.is_j3d_model(content):
                        continue
                    target = native_root / relative_archive / (Path(member).stem + ".n3d")
                    far_target = target.with_suffix(".far")
                    write_native = relative_archive in renew or not is_current_native(target)
                    write_far = not is_current_far(far_target)
                    if not write_native and not write_far:
                        skipped += 1
                        continue
                    if is_converted_j3d(content):
                        try:
                            content = j3d.restore_model(content)
                        except (struct.error, KeyError, IndexError) as error:
                            failures.append((relative_archive, member, error))
                            continue
                    if write_native:
                        if target.is_file():
                            replaced += 1
                        try:
                            result = n3d.convert_model(content, stats, n3d.animated_registers(animations),
                                                       n3d.patterned_materials(animations))
                        except (n3d.N3DError, struct.error, KeyError, IndexError) as error:
                            failures.append((relative_archive, member, error))
                            continue
                        write_atomically(target, result)
                        generated += 1
                        _log(f"native: {target.relative_to(native_root).as_posix()}")
                    else:
                        skipped += 1
                    if write_far:
                        # A model the far builder cannot read keeps its full draws: not a failure.
                        try:
                            far_model = far.build(content, animations)
                        except Exception as error:  # noqa: BLE001 - optional output, never stops the conversion
                            _log(f"far: {far_target.relative_to(native_root).as_posix()}: none ({type(error).__name__}: {error})")
                            far_model = None
                        write_atomically(far_target, far_model or far.none())
                        if far_model:
                            far_written += 1
                            _log(f"far: {far_target.relative_to(native_root).as_posix()}")

            _progress("Native models", len(archives), len(archives), "", force=True)
            if failures:
                print(f"Native conversion found {len(failures)} errors; game files were not written.")
                for relative, member, error in failures[:30]:
                    print(f"  {relative}/{member}: {type(error).__name__}: {error}")
                raise SystemExit(1)
            print(
                f"Native models: generated {generated} (of which {replaced} replaced an existing one), "
                f"already present {skipped}, output {native_root}"
            )
            if far_written:
                print(f"Far models: {far_written} written")

        def copy_original_files(root, originals):
            """The files of the original extraction that the folder lacks; it can start empty."""
            missing = [path for path in _list_files(originals) if not (root / path.relative_to(originals)).exists()]
            needed = sum(path.stat().st_size for path in missing)
            root.mkdir(parents=True, exist_ok=True)
            free = shutil.disk_usage(root).free
            if needed > free:
                raise SystemExit(f"Not enough free space in {root}: {needed >> 20} MB needed, {free >> 20} MB free.")
            for number, path in enumerate(missing, 1):
                relative = path.relative_to(originals)
                _progress("Copying original files", number - 1, len(missing), str(relative))
                target = root / relative
                target.parent.mkdir(parents=True, exist_ok=True)
                temporary = target.with_name(f".{target.name}.{os.getpid()}.tmp")
                try:
                    shutil.copyfile(path, temporary)
                    os.replace(temporary, target)
                finally:
                    if temporary.exists():
                        temporary.unlink()
            _progress("Copying original files", len(missing), len(missing), "", force=True)
            print(f"Original files copied: {len(missing)} ({needed >> 20} MB)")

        def update_outdated_files(root, originals):
            """Converts anew, from the original extraction, what FILE_UPDATES lists for this tree."""
            outdated = _outdated_files(root)
            for number, path in enumerate(outdated, 1):
                relative = path.relative_to(root)
                _progress("Updating files", number - 1, len(outdated), str(relative))
                if originals is None:
                    print(f"Warning: {len(outdated)} converted files are outdated ({relative} and others). "
                          "Choose the original extracted game files to update them; the game still works without.")
                    return
                original = originals / relative
                if not original.is_file():
                    raise SystemExit(f"{relative} not found in {originals}: choose the folder that holds ObjectData.")
                data = original.read_bytes()
                if data[:4] not in (b"Yaz0", b"RARC", b"STRM"):
                    raise SystemExit(f"{original} is already converted: choose the original extraction of the game.")
                result = Converter().convert(path.name, data)
                temporary = path.with_name(f".{path.name}.{os.getpid()}.tmp")
                try:
                    temporary.write_bytes(result)
                    os.replace(temporary, path)
                finally:
                    if temporary.exists():
                        temporary.unlink()
                _log(f"updated: {relative.as_posix()}")
            _progress("Updating files", len(outdated), len(outdated), "", force=True)
            if outdated:
                print(f"Updated {len(outdated)} files from {originals}")
            _files_version_path(root).write_text(str(FILES_VERSION), encoding="ascii")
            write_port_data(root, originals)

        def write_port_data(root, originals):
            """The data files of main.dol into smg/port (block "Game data kept inside main.dol")."""
            if not _port_data_missing(root):
                return
            dol_path = _main_dol_for(originals, root)
            if dol_path is None:
                # Without the original extraction there is no main.dol to read: say what the
                # game needs, since it stops at startup without these files.
                print("Warning: the game data inside main.dol is not on the SD card yet, and the game will not "
                      "start without it. Choose the original extracted game files (the folder Dolphin made, "
                      "with sys/main.dol next to files/) and run the converter again.")
                return
            dol = dol_path.read_bytes()
            if hashlib.sha1(dol).hexdigest() != MAIN_DOL_SHA1:
                raise SystemExit(f"{dol_path} is not the main.dol of Super Mario Galaxy (USA, RMGE01) as the disc "
                                 "has it. Extract the game again with Dolphin.")
            folder = _port_data_folder(root)
            folder.mkdir(parents=True, exist_ok=True)
            for name, address, size in PORT_DATA:
                write_atomically(folder / name, Converter().convert(name, _dol_bytes(dol, address, size)))
                _log(f"port data: {name}")
            print(f"Game data from main.dol written to {folder}")

        script_path = Path(__file__).resolve()
        first_step = "Missing native models" if args.discover_native else "Native models"
        originals = Path(args.originals).expanduser().resolve() if args.originals else None
        if fills_folder:
            if originals is None or not originals.is_dir():
                raise SystemExit("Copying the original files needs --originals with an existing folder.")
            copy_original_files(root, originals)
            if args.only == "copy":
                return 0
        renew_native = _outdated_native(root)  # before the update step records the new version
        if not args.discover_native and args.only in (None, "update"):
            update_outdated_files(root, originals)
            if args.only == "update":
                return 0
        files = [
            path for path in _list_files(root, lambda count: _progress(first_step, 0, None, f"Listing files: {count}"))
            if path.resolve() != script_path
            and path.relative_to(root).parts[0] not in SKIPPED_DIRS
        ]

        native_root = Path(args.native).expanduser().resolve() if args.native else root.parent / "native"
        if args.discover_native:
            return discover_native_files(root, native_root, files)
        if args.only == "movies":
            convert_movies_in_place(root, movie)
            return 0
        if args.only != "convert":
            generate_native_files(root, native_root, files, renew_native)
        if args.only == "native":
            return 0
        if args.native_only:
            pending = [path for path in (root / "MovieData").glob("*.thp") if not movie.is_converted(path)]
            if pending:
                _log(f"Note: {len(pending)} movies in MovieData are not converted yet; "
                     "'Do everything' or 'Convert movies' converts them.")
            return build_file_pack(root, native_root)

        print(f"Scanning {len(files)} files in {root}")
        converted = Counter()
        unchanged = Counter()
        failures = []
        changed = []

        # Preflight first so malformed input does not leave a partly converted tree.
        for number, path in enumerate(files, 1):
            _progress("Checking files", number - 1, len(files), str(path.relative_to(root)))
            try:
                data = path.read_bytes()
                if already_converted(path, data):
                    unchanged["already converted"] += 1
                    continue
                converter = Converter()
                result = converter.convert(path.name, data)
                if result != data:
                    changed.append(path)
                else:
                    unchanged.update(converter.unknown or {"unchanged": 1})
            except Exception as error:
                failures.append((path.relative_to(root), error))

        if failures:
            print(f"Preflight found {len(failures)} conversion errors; no game files were changed.")
            for relative, error in failures[:30]:
                print(f"  {relative}: {type(error).__name__}: {error}")
            return 1

        _progress("Checking files", len(files), len(files), "", force=True)
        print(f"Converting {len(changed)} files in place...")
        for index, path in enumerate(changed, 1):
            _progress("Converting files", index - 1, len(changed), str(path.relative_to(root)))
            try:
                original = path.read_bytes()
                result = Converter().convert(path.name, original)
                if result == original:
                    continue
                temporary = path.with_name(f".smg3ds-convert-{os.getpid()}-{index}.tmp")
                try:
                    with temporary.open("wb") as stream:
                        stream.write(result)
                        stream.flush()
                        os.fsync(stream.fileno())
                    os.replace(temporary, path)
                finally:
                    if temporary.exists():
                        temporary.unlink()
                converted[path.suffix.lower() or path.name] += 1
                _log(f"converted: {path.relative_to(root).as_posix()}")
            except Exception as error:
                failures.append((path.relative_to(root), error))
                break

        if failures:
            print("Conversion stopped during in-place writes:")
            for relative, error in failures:
                print(f"  {relative}: {type(error).__name__}: {error}")
            print("Files written before the error remain converted. Keep the script for recovery.")
            return 1

        print("Converted:")
        for kind, count in converted.most_common():
            print(f"  {kind}: {count}")
        print(f"Already converted or unchanged: {sum(unchanged.values())}")
        if args.only == "convert":
            return 0
        convert_movies_in_place(root, movie)
        build_file_pack(root, native_root)
        print("Done. The game's files were overwritten in this folder.")
        return 0


def convert_movies_in_place(root, movie):
    """MovieData/*.thp to the 3DS movie format (H.264 for the New 3DS video decoder, the THP's
    DSP-ADPCM audio; about 25 times smaller). Needs ffmpeg; without it the movies are left as they
    are and the game skips them."""
    step = "Movies"
    if not (root / "MovieData").is_dir():
        _log("Movies: no MovieData folder in the selected files folder; the game skips the movies.")
        return
    movies = sorted(path for path in (root / "MovieData").glob("*.thp") if not _is_hidden(path))
    pending = [path for path in movies if not movie.is_converted(path)]
    if not pending:
        _progress(step, 1, 1, "", force=True)
        print(f"Movies: {len(movies)} already converted.")
        return
    ffmpeg = _ensure_ffmpeg(movie, step)
    if ffmpeg is None:
        print("Movies: no ffmpeg with H.264 (libx264) could be found or downloaded; MovieData left as it is, "
              "the game skips the movies. Install ffmpeg and run the conversion again.")
        return
    _log(f"Movies: converting {len(pending)} with {ffmpeg} (a few minutes each)")
    for index, path in enumerate(pending, 1):
        temporary = path.with_name(f".smg3ds-convert-{os.getpid()}-movie.tmp")

        def report(fraction, index=index, path=path):
            _progress(step, (index - 1 + fraction) * 1000, len(pending) * 1000,
                      f"{path.name} ({index} of {len(pending)}): {fraction * 100:.0f}%")

        report(0.0)
        try:
            result = movie.convert(str(path), str(temporary), ffmpeg, report)
            os.replace(temporary, path)
        finally:
            if temporary.exists():
                temporary.unlink()
        print(f"Movie {index}/{len(pending)}: {path.name}, {result['bytes'] / 1e6:.1f} MB", flush=True)


def _conversion_state(source, all_files=None, progress=None):
    """("original" | "converted" | "mixed" | "missing", converted files, files), from the first
    bytes of each file; progress(percent, text) per file."""
    signatures = {".brlyt": b"TYLR", ".brlan": b"NALR", ".brfnt": b"TNFR", ".ast": b"MRTS"}
    total = converted = 0
    if not source.is_dir():
        return "missing", 0, 0
    if all_files is None:
        all_files = _list_files(source)
    for number, path in enumerate(all_files, 1):
        if progress and (number % 50 == 0 or number == len(all_files)):
            progress(100.0 * number / len(all_files), f"Checking conversion state ({number}/{len(all_files)})...")
        total += 1
        try:
            with path.open("rb") as stream:
                data = stream.read(0x20)
        except OSError:
            continue
        converted_file = data[:4] in (b"CRAR", b"<_AA")
        converted_file |= data[:4] == signatures.get(path.suffix.lower())
        converted_file |= path.suffix.lower() == ".tpl" and data[:4] == b"\x30\xaf\x20\x00"
        converted_file |= data[:4] == b"THP\0" and int.from_bytes(data[4:8], "little") == MOVIE_VERSION
        if path.suffix.lower() == ".bmg" and len(data) >= 0x20:
            be_count = int.from_bytes(data[0x0C:0x10], "big")
            le_count = int.from_bytes(data[0x0C:0x10], "little")
            converted_file |= le_count <= 32 < be_count
        converted += int(converted_file)
    return ("original" if not converted else "converted" if converted == total else "mixed"), converted, total


def _settings_path():
    return Path.home() / ".smg3ds_converter.json"


def _load_originals():
    """The saved folder of the original files, or "" when none is saved or it no longer looks right."""
    try:
        path = Path(json.loads(_settings_path().read_text(encoding="utf-8"))["originals"])
        archives = sorted((path / "ObjectData").glob("*.arc"))[:5]
        if archives and all(a.read_bytes()[:4] in (b"Yaz0", b"RARC") for a in archives):
            return str(path)
    except (OSError, ValueError, KeyError, TypeError):
        pass
    return ""


def _save_originals(path):
    _settings_path().write_text(json.dumps({"originals": str(path)}, indent=2), encoding="utf-8")


def _check_originals(path, progress=None):
    """(the folder to use, errors) for a folder chosen as the original files: the extracted tree,
    or the folder above it that holds files/, with nothing converted."""
    if (path / "files" / "ObjectData").is_dir():
        path = path / "files"
    if not path.is_dir():
        return path, ["The folder does not exist."]
    files = _list_files(path, progress and (lambda count: progress(f"Listing files: {count} found...")))
    errors, _ = _validate_source_tree(path, None, files)
    if errors:
        return path, errors
    state, converted, total = _conversion_state(path, files, progress and (lambda _, text: progress(text)))
    if state != "original":
        return path, [f"{converted} of {total} files are already converted. Choose the files as Dolphin extracted them, "
                      "or extract them again."]
    return path, []


def _validate_source_tree(source, progress=None, all_files=None):
    """Return targeted errors and warnings for an extracted SMG files tree. progress(percent,
    text), percent -1 while listing the files."""
    errors = []
    warnings = []
    if not source.is_dir():
        return ["The selected path is not a directory."], warnings

    if all_files is None:
        all_files = _list_files(source, progress and (lambda count: progress(-1, f"Listing files: {count} found...")))
    total_files = len(all_files)
    if progress:
        progress(5, f"Found {total_files} files; checking the game directory structure...")
    required_directories = ("AudioRes", "ObjectData", "LayoutData", "StageData")
    for name in required_directories:
        directory = source / name
        if not directory.is_dir():
            errors.append(f"Missing required game directory: {name}")
        elif not any(path.is_relative_to(directory) for path in all_files):
            errors.append(f"Required game directory is empty: {name}")

    def archive_candidates(directory):
        return [
            path for path in all_files
            if path.is_relative_to(directory) and path.suffix.lower() in (".arc", ".szs", ".bdl", ".bmd")
        ] if directory.is_dir() else []

    object_archives = archive_candidates(source / "ObjectData")
    layout_archives = archive_candidates(source / "LayoutData")
    stage_archives = archive_candidates(source / "StageData")
    if not object_archives:
        errors.append("ObjectData contains no .arc, .szs, .bdl, or .bmd assets.")
    if not layout_archives:
        errors.append("LayoutData contains no layout archives.")
    if not stage_archives:
        errors.append("StageData contains no stage archives.")

    valid_archive_headers = {b"RARC", b"Yaz0", b"YAZ0", b"CRAR", b"<_AA"}
    inspected = 0
    recognized = 0
    sampled_archives = object_archives[:64] + layout_archives[:64] + stage_archives[:64]
    for index, path in enumerate(sampled_archives, 1):
        try:
            with path.open("rb") as stream:
                header = stream.read(4)
        except OSError as error:
            warnings.append(f"Could not read {path.relative_to(source)}: {error}")
            continue
        inspected += 1
        if header in valid_archive_headers:
            recognized += 1
        if progress:
            progress(70 + int(index * 30 / max(1, len(sampled_archives))),
                     f"Checking archive headers ({index}/{len(sampled_archives)})...")
    if inspected and recognized == 0:
        errors.append("No recognizable Wii/3DS archive headers were found in the game asset directories.")
    elif inspected and recognized < inspected:
        warnings.append(f"{inspected - recognized} sampled asset files have unrecognized headers.")

    if not any(path.is_relative_to(source / "AudioRes") for path in all_files):
        errors.append("AudioRes contains no files; this is not a complete extracted files directory.")
    if not any(path.suffix.lower() == ".arc" for path in all_files):
        warnings.append("No .arc files were found; native model discovery may find no models.")
    if not any(path.suffix.lower() == ".thp" and path.parent.name == "MovieData" for path in all_files):
        warnings.append("No MovieData folder with .thp movies: copy it from the game's files folder, "
                        "or the game skips the movies.")
    if progress:
        progress(100, "Directory validation complete.")
    return errors, warnings


def _tkinter_help():
    if sys.platform == "darwin":
        return ("Install Python from python.org (it includes Tk), or with Homebrew: brew install python-tk.\n"
                "The CLI works without it: python3 convert_smg_files.py --source <smg/files>")
    if os.name == "nt":
        return "Reinstall Python from python.org with the 'tcl/tk and IDLE' option checked."
    return ("Install Tk for Python: sudo apt install python3-tk (Debian/Ubuntu), sudo dnf install python3-tkinter "
            "(Fedora), sudo pacman -S tk (Arch).\nThe CLI works without it: python3 convert_smg_files.py --source <smg/files>")


def run_gui():
    try:
        import tkinter as tk
        from tkinter import filedialog, messagebox, ttk
    except ImportError as error:
        raise SystemExit("Tkinter is required for the GUI: %s\n%s" % (error, _tkinter_help()))

    spinner = "|/-\\"
    log_limit = 4000  # lines kept in the log panel

    def ask_originals(root, current="", message=""):
        """The popup for the original files: the checked and saved folder, or None if closed."""
        dialog = tk.Toplevel(root)
        dialog.title("Original game files")
        dialog.resizable(False, False)
        if root.winfo_viewable():
            dialog.transient(root)
        chosen = {"path": None}
        results = queue.Queue()
        folder = tk.StringVar(value=current)
        status = tk.StringVar(value=message)
        ttk.Label(dialog, wraplength=560, justify="left",
                  text="Choose the folder with the game files extracted from Dolphin, not converted (it holds ObjectData, "
                       "StageData, LayoutData and AudioRes). The converter uses it to update converted files and never "
                       "changes it.").pack(padx=14, pady=(14, 8), anchor="w")
        row = ttk.Frame(dialog)
        row.pack(fill="x", padx=14)
        entry = ttk.Entry(row, textvariable=folder, width=64)
        entry.pack(side="left", fill="x", expand=True)

        def browse():
            path = filedialog.askdirectory(parent=dialog, title="Select the original files extracted from Dolphin")
            if path:
                folder.set(path)

        browse_button = ttk.Button(row, text="Browse...", command=browse)
        browse_button.pack(side="left", padx=(6, 0))
        ttk.Label(dialog, textvariable=status, wraplength=560, justify="left").pack(padx=14, pady=8, anchor="w")
        buttons = ttk.Frame(dialog)
        buttons.pack(padx=14, pady=(0, 14), anchor="e")

        def set_enabled(state):
            for widget in (entry, browse_button, ok_button):
                widget.configure(state=state)

        def run_checks(path):
            try:
                results.put(_check_originals(path, results.put))
            except Exception as error:
                results.put((path, [str(error)]))

        def poll():
            while True:
                try:
                    result = results.get_nowait()
                except queue.Empty:
                    dialog.after(50, poll)
                    return
                if isinstance(result, str):
                    status.set(result)
                    continue
                path, errors = result
                if not errors:
                    try:
                        _save_originals(path)
                    except OSError as error:
                        errors = [f"Cannot save the settings file: {error}"]
                if errors:
                    status.set("\n".join(errors))
                    set_enabled("normal")
                    return
                chosen["path"] = str(path)
                dialog.destroy()
                return

        def confirm():
            if not folder.get().strip():
                status.set("Choose a folder first.")
                return
            set_enabled("disabled")
            status.set("Checking the folder...")
            threading.Thread(target=run_checks, args=(Path(folder.get().strip()).expanduser().resolve(),), daemon=True).start()
            poll()

        ok_button = ttk.Button(buttons, text="Continue", command=confirm)
        ok_button.pack(side="left", padx=3)
        ttk.Button(buttons, text="Close", command=dialog.destroy).pack(side="left", padx=3)
        dialog.protocol("WM_DELETE_WINDOW", dialog.destroy)
        dialog.grab_set()
        dialog.wait_window()
        return chosen["path"]

    class ConverterGui:
        def __init__(self, root, originals):
            self.root = root
            self.process = None
            self.events = queue.Queue()  # filled by worker threads, drained on the Tk thread
            self.started = None
            self.last_event = 0.0
            self.tick = 0
            self.source = tk.StringVar()
            self.native = tk.StringVar()
            self.originals = tk.StringVar(value=originals)
            self.step_value = tk.DoubleVar()
            self.total_value = tk.DoubleVar()
            root.title("SMG 3DS Converter")
            root.geometry("920x760")
            root.minsize(780, 720)
            paths = ttk.LabelFrame(root, text="Folders")
            paths.pack(fill="x", padx=12, pady=10)
            ttk.Label(paths, text="smg/files:").grid(row=0, column=0, padx=8, pady=8)
            ttk.Entry(paths, textvariable=self.source).grid(row=0, column=1, sticky="ew", padx=4)
            ttk.Button(paths, text="Browse...", command=self.choose_source).grid(row=0, column=2, padx=8)
            ttk.Label(paths, text="smg/native:").grid(row=1, column=0, padx=8, pady=8)
            ttk.Entry(paths, textvariable=self.native).grid(row=1, column=1, sticky="ew", padx=4)
            ttk.Button(paths, text="Browse...", command=self.choose_native).grid(row=1, column=2, padx=8)
            ttk.Label(paths, text="Original files:").grid(row=2, column=0, padx=8, pady=8)
            ttk.Entry(paths, textvariable=self.originals, state="readonly").grid(row=2, column=1, sticky="ew", padx=4)
            ttk.Button(paths, text="Change...", command=self.change_originals).grid(row=2, column=2, padx=8)
            paths.columnconfigure(1, weight=1)
            self.buttons = []
            ttk.Style(root).configure("Main.TButton", font=("TkDefaultFont", 13, "bold"), padding=(26, 10))
            main_action = ttk.Frame(root)
            main_action.pack(fill="x", padx=12)
            main_button = ttk.Button(main_action, text="Do everything", style="Main.TButton", command=lambda: self.start("all"))
            main_button.pack()
            ttk.Label(main_action, justify="center", wraplength=700,
                      text="From the original files to the SD cache, in order: copy, update, native models, "
                           "game files, movies, cache. What is already done is skipped.").pack(pady=(3, 8))
            self.buttons.append(main_button)
            parts = ttk.LabelFrame(root, text="Single parts")
            parts.pack(fill="x", padx=12)
            action_specs = (
                ("Copy originals", "Copy the files smg/files lacks.", "copy"),
                ("Update old files", "Redo files an older converter wrote.", "update"),
                ("Native models", "Write the missing .n3d files.", "native"),
                ("Convert files", "Convert the game files in place.", "convert"),
                ("Convert movies", "Convert MovieData.", "movies"),
                ("SD cache", "Write smg/cache.", "pack"),
                ("Find missing", "Report missing native models.", "discover"),
            )
            for label, caption, mode in action_specs:
                action = ttk.Frame(parts)
                action.pack(side="left", padx=4, pady=6, fill="y", expand=True)
                button = ttk.Button(action, text=label, command=lambda m=mode: self.start(m))
                button.pack()
                ttk.Label(action, text=caption, wraplength=105, justify="center").pack(pady=(3, 0))
                self.buttons.append(button)

            progress = ttk.LabelFrame(root, text="Progress")
            progress.pack(fill="x", padx=12, pady=(10, 0))
            self.step_label = ttk.Label(progress, text="Choose the smg/files directory.")
            self.step_label.grid(row=0, column=0, columnspan=2, sticky="w", padx=8, pady=(6, 2))
            self.step_bar = ttk.Progressbar(progress, maximum=100, variable=self.step_value)
            self.step_bar.grid(row=1, column=0, sticky="ew", padx=8)
            self.step_percent = ttk.Label(progress, text="", width=8, anchor="e")
            self.step_percent.grid(row=1, column=1, padx=(0, 8))
            self.detail = ttk.Label(progress, text="", foreground="gray")
            self.detail.grid(row=2, column=0, columnspan=2, sticky="w", padx=8, pady=(2, 4))
            self.total_label = ttk.Label(progress, text="Total")
            self.total_label.grid(row=3, column=0, columnspan=2, sticky="w", padx=8)
            ttk.Progressbar(progress, maximum=100, variable=self.total_value).grid(row=4, column=0, sticky="ew", padx=8)
            self.total_percent = ttk.Label(progress, text="", width=8, anchor="e")
            self.total_percent.grid(row=4, column=1, padx=(0, 8))
            bottom = ttk.Frame(progress)
            bottom.grid(row=5, column=0, columnspan=2, sticky="ew", padx=8, pady=6)
            self.clock = ttk.Label(bottom, text="")
            self.clock.pack(side="left")
            self.stop_button = ttk.Button(bottom, text="Stop", command=self.stop, state="disabled")
            self.stop_button.pack(side="right")
            progress.columnconfigure(0, weight=1)

            frame = ttk.LabelFrame(root, text="Log")
            frame.pack(fill="both", expand=True, padx=12, pady=10)
            self.log = tk.Text(frame, state="disabled", wrap="none", height=10)
            scroll = ttk.Scrollbar(frame, command=self.log.yview)
            self.log.configure(yscrollcommand=scroll.set)
            scroll.pack(side="right", fill="y")
            self.log.pack(side="left", fill="both", expand=True)
            root.protocol("WM_DELETE_WINDOW", self.close)
            self.root.after(100, self.poll)

        # Worker threads only put events in the queue; this loop (Tk thread) applies them and keeps
        # the clock and the spinner moving, so the window never looks stuck.
        def poll(self):
            lines = []
            latest = None
            try:
                for _ in range(2000):
                    event = self.events.get_nowait()
                    if event[0] == "log":
                        lines.append(event[1])
                    elif event[0] == "progress":
                        latest = event
                    else:
                        if lines:
                            self.append("".join(lines))
                            lines = []
                        if latest:
                            self.show_progress(*latest[1:])
                            latest = None
                        event[1](*event[2:])
            except queue.Empty:
                pass
            if lines:
                self.append("".join(lines))
            if latest:
                self.show_progress(*latest[1:])
            self.tick += 1
            if self.started is not None:
                elapsed = int(time.monotonic() - self.started)
                quiet = time.monotonic() - self.last_event
                note = "  (working on a long step...)" if quiet > 3 else ""
                self.clock.configure(text=f"{spinner[self.tick % 4]}  Elapsed {elapsed // 60:02d}:{elapsed % 60:02d}{note}")
                if str(self.step_bar.cget("mode")) == "indeterminate":
                    self.step_bar.step(2)
            self.root.after(100, self.poll)

        def post(self, *event):
            self.events.put(event)

        def append(self, text):
            self.log.configure(state="normal")
            self.log.insert("end", text)
            extra = int(self.log.index("end-1c").split(".")[0]) - log_limit
            if extra > 0:
                self.log.delete("1.0", f"{extra + 1}.0")
            self.log.see("end")
            self.log.configure(state="disabled")

        def show_progress(self, step, steps, percent, name, detail):
            self.last_event = time.monotonic()
            prefix = f"Step {step} of {steps}: " if step and steps else ""
            self.step_label.configure(text=prefix + name)
            self.detail.configure(text=detail[:150])
            if percent < 0:
                if str(self.step_bar.cget("mode")) != "indeterminate":
                    self.step_bar.configure(mode="indeterminate")
                self.step_percent.configure(text="...")
            else:
                if str(self.step_bar.cget("mode")) != "determinate":
                    self.step_bar.configure(mode="determinate")
                self.step_value.set(percent)
                self.step_percent.configure(text=f"{percent:.1f}%")
            if step and steps:
                total = 100.0 * (step - 1 + max(percent, 0) / 100.0) / steps
                self.total_value.set(total)
                self.total_percent.configure(text=f"{total:.1f}%")

        def reset_progress(self):
            self.step_bar.configure(mode="determinate")
            self.step_value.set(0)
            self.total_value.set(0)
            self.step_percent.configure(text="0.0%")
            self.total_percent.configure(text="0.0%")
            self.detail.configure(text="")

        def choose_source(self):
            path = filedialog.askdirectory(title="Select smg/files")
            if path:
                self.source.set(path)
                if not self.native.get():
                    self.native.set(str(Path(path).parent / "native"))

        def choose_native(self):
            path = filedialog.askdirectory(title="Select smg/native")
            if path:
                self.native.set(path)

        def change_originals(self):
            if self.process and self.process.poll() is None:
                messagebox.showerror("SMG 3DS Converter", "Wait for the running operation to end first.")
                return
            path = ask_originals(self.root, self.originals.get())
            if path is None or path == self.originals.get():
                return
            messagebox.showinfo("SMG 3DS Converter", "The original files folder has changed: the converter restarts.")
            self.root.destroy()
            subprocess.Popen([sys.executable, str(Path(__file__).resolve()), "--gui"])

        def set_buttons(self, enabled):
            state = "normal" if enabled else "disabled"
            for button in self.buttons:
                button.configure(state=state)

        def begin(self):
            self.set_buttons(False)
            self.reset_progress()
            self.started = self.last_event = time.monotonic()

        def end(self, text):
            self.set_buttons(True)
            self.stop_button.configure(state="disabled")
            self.started = None
            self.step_bar.configure(mode="determinate")
            elapsed = self.clock.cget("text").split("Elapsed")[-1].split("(")[0].strip()
            self.clock.configure(text=f"{text}  ({elapsed})" if elapsed else text)

        def start(self, mode):
            if not self.source.get().strip():
                messagebox.showerror("SMG 3DS Converter", "Choose the smg/files directory first (it can be an empty folder).")
                return
            source = Path(self.source.get()).expanduser().resolve()
            if not self.native.get().strip():
                self.native.set(str(source.parent / "native"))
            originals = Path(self.originals.get()).resolve()
            if source == originals or originals in source.parents:
                # The conversion works in place: it would destroy the only originals.
                messagebox.showerror("SMG 3DS Converter", "smg/files is the original files folder. The conversion overwrites "
                                     "it: choose a copy of the files for smg/files.")
                return
            native = Path(self.native.get()).expanduser().resolve() if self.native.get() else source.parent / "native"
            self.begin()
            self.append(f"\n> Validating {source}\n")
            threading.Thread(target=self.validate_in_background, args=(mode, source, native), daemon=True).start()

        def validate_in_background(self, mode, source, native):
            # Validation counts for 40% of its bar, reading the conversion state for the rest.
            def report(value, text):
                self.post("progress", 1, 1, -1.0 if value < 0 else 0.4 * value, "Validating the game directory", text)

            def report_state(value, text):
                self.post("progress", 1, 1, 40 + 0.6 * value, "Validating the game directory", text)

            try:
                if mode in ("all", "copy"):
                    # The operation fills the folder. Any other folder with files would get them
                    # overwritten by the conversion.
                    if source.is_file() or (source.is_dir() and any(source.iterdir()) and not (source / "ObjectData").is_dir()):
                        raise OSError(f"{source} holds other files: choose smg/files or an empty folder.")
                    self.post("call", self.finish_validation, (mode, source, native, [], [], None, 0, 0, None))
                    return
                if not source.is_dir():
                    raise OSError(f"{source} is not a folder.")
                files = _list_files(source, lambda count: report(-1, f"Listing files: {count} found..."))
                errors, warnings = _validate_source_tree(source, report, files)
                state, converted, total = _conversion_state(source, files, report_state) if not errors else (None, 0, 0)
                result = (mode, source, native, errors, warnings, state, converted, total, None)
            except Exception as error:
                result = (mode, source, native, [], [], None, 0, 0, error)
            self.post("call", self.finish_validation, result)

        def finish_validation(self, result):
            mode, source, native, errors, warnings, state, converted, total, exception = result
            if exception is not None:
                self.end("Validation failed.")
                messagebox.showerror("Validation failed", str(exception))
                return
            if errors:
                self.end("Invalid game directory.")
                messagebox.showerror(
                    "Invalid game directory",
                    "The selected path is not a valid extracted SMG files directory:\n\n"
                    + "\n".join(f"- {error}" for error in errors),
                )
                return
            self.append("Validation passed.\n")
            for warning in warnings:
                self.append(f"Warning: {warning}\n")
            self.run_job(mode, source, native)

        def run_job(self, mode, source, native):
            self.reset_progress()
            self.append(f"\n> {mode}: {source} -> {native}\n")
            command = [sys.executable, "-u", str(Path(__file__).resolve()), "--source", str(source),
                       "--native", str(native), "--validated"]
            if mode in ("all", "copy", "update"):
                command += ["--originals", self.originals.get()]
            if mode in ("copy", "update", "native", "convert", "movies"):
                command += ["--only", mode]
            elif mode == "discover":
                command.append("--discover-native")
            elif mode == "pack":
                command.append("--pack-only")
            environment = dict(os.environ, PYTHONIOENCODING="utf-8", PYTHONUNBUFFERED="1")
            self.process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                            stdin=subprocess.DEVNULL, text=True, encoding="utf-8",
                                            errors="replace", env=environment, creationflags=NO_WINDOW)
            self.stop_button.configure(state="normal")
            threading.Thread(target=self.read_job, args=(self.process,), daemon=True).start()

        def read_job(self, process):
            for line in process.stdout:
                if line.startswith("@@PROGRESS "):
                    parts = line.rstrip("\n").split(" ", 4)
                    name, _, detail = parts[4].partition("|") if len(parts) == 5 else ("", "", "")
                    try:
                        self.post("progress", int(parts[1]), int(parts[2]), float(parts[3]), name, detail)
                    except (ValueError, IndexError):
                        self.post("log", line)
                else:
                    self.post("log", line)
            self.post("call", self.finish_job, process.wait())

        def stop(self):
            if self.process and self.process.poll() is None:
                if messagebox.askyesno("SMG 3DS Converter", "Stop the operation? Files already written stay as they are; "
                                       "running the same operation again resumes it."):
                    self.process.terminate()

        def close(self):
            if self.process and self.process.poll() is None:
                if not messagebox.askyesno("SMG 3DS Converter", "An operation is running. Stop it and close?"):
                    return
                self.process.terminate()
            self.root.destroy()

        def finish_job(self, code):
            self.process = None
            if code == 0:
                self.step_value.set(100)
                self.total_value.set(100)
                self.step_percent.configure(text="100.0%")
                self.total_percent.configure(text="100.0%")
            self.end("Completed." if code == 0 else f"Failed or stopped ({code}). See the log.")
            (messagebox.showinfo if code == 0 else messagebox.showerror)(
                "SMG 3DS Converter", "Operation completed." if code == 0 else "Operation failed or stopped. See the log.")

    try:
        root = tk.Tk()
    except tk.TclError as error:
        raise SystemExit("Cannot open the GUI window: %s\n%s" % (error, _tkinter_help()))
    root.withdraw()
    originals = _load_originals() or ask_originals(root)
    if originals is None:
        root.destroy()
        return
    root.deiconify()
    ConverterGui(root, originals)
    root.mainloop()


if __name__ == "__main__":
    raise SystemExit(main())
